<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:30px}body{font-family:DejaVu Sans,sans-serif;color:#222}.card{border:1px solid #222;height:330px;position:relative;padding:18px}.barcode{text-align:center;height:55px}.barcode svg{height:50px}.data{font-size:15px;line-height:1.75}.label{font-weight:bold}.side{position:absolute;right:0;top:0;height:100%;width:72px;border-left:1px solid #222;writing-mode:vertical-rl;transform:rotate(180deg);text-align:center;font-weight:bold;letter-spacing:1px}.main{padding-right:70px}.footer{border-top:1px dashed #777;text-align:center;margin-top:10px;font-weight:bold}</style></head><body><div class="card"><div class="side">{{ strtoupper(config('app.name', 'RECRUITMENT')) }}</div><div class="main"><div class="barcode">{!! $barcodeSvg !!}</div><div class="data"><div><span class="label">ENTRY DATE :</span> {{ $recruitment->created_at?->format('d/m/Y') }}</div><div><span class="label">COMPANY :</span> {{ $recruitment->company?->name ?? '—' }}</div><div><span class="label">CANDIDATE CODE :</span> {{ $recruitment->tracking_number }}</div><div><span class="label">NAME :</span> {{ $holder?->full_name ?? '—' }}</div><div><span class="label">PP NO :</span> {{ $holder?->passport_number ?? '—' }} &nbsp; <span class="label">PP EXP :</span> {{ $holder?->passport_expiry_date?->format('Y-m-d') ?? '—' }}</div><div><span class="label">MEDICAL DATE :</span> {{ $recruitment->medical?->medical_date?->format('d/m/Y') ?? '—' }}</div><div><span class="label">MEDICAL STATUS :</span> {{ strtoupper($recruitment->medical?->result ?? 'PENDING') }}</div><div><span class="label">COUNTRY :</span> {{ $recruitment->country?->name ?? '—' }}</div><div><span class="label">AGENT CODE :</span> {{ $recruitment->agent ? 'AG'.str_pad((string) $recruitment->agent->id, 5, '0', STR_PAD_LEFT) : '—' }}</div><div><span class="label">AGENT NAME :</span> {{ $recruitment->agent?->name ?? '—' }}</div></div><div class="footer">{{ config('app.name') }}</div></div></div></body></html>
